import{A as e,H as t,P as n,_ as r,a as i,f as a,g as o,h as s,t as c,u as l}from"./chunks/plugin-vue_export-helper.I53torQa.js";var u=JSON.parse(`{"title":"LLM 推理经典论文与前沿进展","description":"按服务系统、KV Cache、Kernel、解码加速、量化和集群架构整理 LLM 推理经典论文，并补充 2024–2026 年前沿进展、官方博客与工程实践入口。","frontmatter":{"title":"LLM 推理经典论文与前沿进展","description":"按服务系统、KV Cache、Kernel、解码加速、量化和集群架构整理 LLM 推理经典论文，并补充 2024–2026 年前沿进展、官方博客与工程实践入口。"},"headers":[],"relativePath":"inference/foundations/classic-papers-and-blogs.md","filePath":"inference/foundations/classic-papers-and-blogs.md","lastUpdated":1787709476000}`),d={name:`inference/foundations/classic-papers-and-blogs.md`};function f(c,u,d,f,p,m){let h=n(`Mermaid`);return e(),a(`div`,null,[u[1]||=s(`<h1 id="llm-推理经典论文与前沿进展" tabindex="-1">LLM 推理经典论文与前沿进展 <a class="header-anchor" href="#llm-推理经典论文与前沿进展" aria-label="Permalink to “LLM 推理经典论文与前沿进展”">​</a></h1><p>本文面向希望系统学习 LLM 推理的工程师和研究者，整理对当前推理栈影响较大的论文、博客和开源项目，并单独跟踪 2024–2026 年的新进展。这里的“经典”指奠定主流方法、被后续系统广泛采用或提供重要基线的工作；“前沿”则包含已发表论文、预印本和快速演进的工程系统，成熟度并不相同。</p><blockquote><p>更新时间：2026 年 8 月。论文链接优先使用 arXiv、USENIX、ACL Anthology 或 DOI 页面；工程资料指向官方博客、文档或代码仓库。</p></blockquote><h2 id="_1-先建立全局视角" tabindex="-1">1. 先建立全局视角 <a class="header-anchor" href="#_1-先建立全局视角" aria-label="Permalink to “1. 先建立全局视角”">​</a></h2><h3 id="_1-1-请求生命周期" tabindex="-1">1.1 请求生命周期 <a class="header-anchor" href="#_1-1-请求生命周期" aria-label="Permalink to “1.1 请求生命周期”">​</a></h3><p>一次生成请求通常包含两个阶段：</p><ul><li><strong>Prefill</strong>：一次性处理输入 Prompt，计算密集，关注 Attention Kernel、并行度和长上下文效率。</li><li><strong>Decode</strong>：逐 Token 自回归生成，通常受显存带宽和 KV Cache 访问限制，关注调度、批处理、缓存和解码加速。</li></ul><p>常用服务指标：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>适用场景</th></tr></thead><tbody><tr><td>TTFT</td><td>Time To First Token，首 Token 延迟</td><td>交互式请求、长 Prompt</td></tr><tr><td>ITL</td><td>Inter-Token Latency，相邻流式 Token 的时间间隔</td><td>流式输出体验和抖动</td></tr><tr><td>TPOT</td><td>Time Per Output Token，通常按请求统计的平均输出 Token 时间</td><td>Decode 性能比较</td></tr><tr><td>Throughput</td><td>tokens/s、requests/s</td><td>离线任务和容量规划</td></tr><tr><td>Goodput</td><td>满足延迟 SLO 的有效吞吐</td><td>在线服务选型</td></tr><tr><td>显存占用</td><td>权重、KV Cache、激活和通信 Buffer 的总和</td><td>并发上限和模型放置</td></tr></tbody></table></div><p>这一区分解释了为什么同一个优化在 Prefill 和 Decode 阶段的收益可能完全不同：FlashAttention 通常对长 Prompt 的 Prefill 收益更明显；PagedAttention 和连续批处理主要提升 KV Cache 利用率与并发；speculative decoding 则尝试减少串行 Decode 轮数。</p><h3 id="_1-2-技术地图" tabindex="-1">1.2 技术地图 <a class="header-anchor" href="#_1-2-技术地图" aria-label="Permalink to “1.2 技术地图”">​</a></h3>`,11),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-124`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20A%5B%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%5D%20--%3E%20B%5B%E8%B7%AF%E7%94%B1%E4%B8%8E%E6%8E%92%E9%98%9F%5D%0A%20%20B%20--%3E%20C%5BPrefill%5D%0A%20%20C%20--%3E%20D%5BKV%20Cache%20%E5%86%99%E5%85%A5%E6%88%96%E4%BC%A0%E8%BE%93%5D%0A%20%20D%20--%3E%20E%5BDecode%5D%0A%20%20E%20--%3E%20F%5B%E6%B5%81%E5%BC%8F%E8%BE%93%E5%87%BA%5D%0A%0A%20%20C%20-.%E4%BC%98%E5%8C%96.-%3E%20C1%5BFlashAttention%20%2F%20Sparse%20Attention%5D%0A%20%20D%20-.%E4%BC%98%E5%8C%96.-%3E%20D1%5BPagedAttention%20%2F%20Prefix%20Cache%20%2F%20Offload%5D%0A%20%20E%20-.%E4%BC%98%E5%8C%96.-%3E%20E1%5BContinuous%20Batching%20%2F%20Speculative%20Decoding%5D%0A%20%20B%20-.%E9%9B%86%E7%BE%A4%E5%8C%96.-%3E%20B1%5BPD%20%E8%A7%A3%E8%80%A6%20%2F%20Cache-aware%20Routing%5D%0A%20%20C1%20-.%E8%B7%A8%E9%98%B6%E6%AE%B5.-%3E%20G%5B%E9%87%8F%E5%8C%96%20%2F%20%E5%B9%B6%E8%A1%8C%20%2F%20Kernel%20Fusion%5D%0A%20%20E1%20-.%E8%B7%A8%E9%98%B6%E6%AE%B5.-%3E%20G%0A`})]),fallback:t(()=>[...u[0]||=[o(` Loading... `,-1)]]),_:1})),u[2]||=s(`<p>阅读论文时先判断它优化的是哪一段数据路径，再检查代价是否转移到了其他阶段。例如 KV Cache Offload 能提高容量，但可能将瓶颈转移到 PCIe 或网络；量化能降低带宽，却可能因为缺少匹配 Kernel 而无法转化为端到端收益。</p><h3 id="_1-3-资料成熟度" tabindex="-1">1.3 资料成熟度 <a class="header-anchor" href="#_1-3-资料成熟度" aria-label="Permalink to “1.3 资料成熟度”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>类型</th><th>可以回答的问题</th><th>使用时的注意事项</th></tr></thead><tbody><tr><td>同行评审论文</td><td>方法是否新颖，实验基线是否完整</td><td>结果通常绑定论文中的硬件、模型和负载</td></tr><tr><td>arXiv 预印本</td><td>近期研究方向和实现思路</td><td>版本可能变化，结论尚未充分复核</td></tr><tr><td>官方博客/文档</td><td>当前框架如何实现和配置功能</td><td>性能数据可能针对自家软硬件最优配置</td></tr><tr><td>开源仓库</td><td>功能是否真正可运行，接口和限制是什么</td><td>应固定 Commit/Release，避免只参考主分支</td></tr></tbody></table></div><p>站内专题可继续阅读 <a href="/llmtechsite/inference/foundations/inference-metrics">推理核心指标</a>、<a href="/llmtechsite/inference/inference-optimization/continuous-batching">连续批处理</a>、<a href="/llmtechsite/inference/inference-optimization/kv-cache-connector">KV Cache 管理架构</a> 和 <a href="/llmtechsite/inference/inference-optimization/pd-disaggregation">Prefill-Decode 解耦</a>。</p><h2 id="_2-经典论文" tabindex="-1">2. 经典论文 <a class="header-anchor" href="#_2-经典论文" aria-label="Permalink to “2. 经典论文”">​</a></h2><h3 id="_2-1-服务系统与调度" tabindex="-1">2.1 服务系统与调度 <a class="header-anchor" href="#_2-1-服务系统与调度" aria-label="Permalink to “2.1 服务系统与调度”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>论文</th><th style="text-align:right;">年份</th><th>关键思想与影响</th></tr></thead><tbody><tr><td><a href="https://www.usenix.org/conference/osdi22/presentation/yu" target="_blank" rel="noreferrer">Orca: A Distributed Serving System for Transformer-Based Generative Models</a></td><td style="text-align:right;">2022</td><td>提出 iteration-level scheduling 和 selective batching，是连续批处理的早期代表。</td></tr><tr><td><a href="https://arxiv.org/abs/2207.00032" target="_blank" rel="noreferrer">DeepSpeed Inference: Enabling Efficient Inference of Transformer Models at Unprecedented Scale</a></td><td style="text-align:right;">2022</td><td>系统结合张量/流水线并行、Kernel Fusion、量化和大模型分层部署。</td></tr><tr><td><a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noreferrer">Efficient Memory Management for LLM Serving with PagedAttention</a></td><td style="text-align:right;">2023</td><td>将 KV Cache 按 Block 管理，减少碎片和预留浪费，直接催生 vLLM。</td></tr><tr><td><a href="https://arxiv.org/abs/2303.06865" target="_blank" rel="noreferrer">FlexGen: High-Throughput Generative Inference of Large Language Models with a Single GPU</a></td><td style="text-align:right;">2023</td><td>将权重、激活和 KV Cache 在 GPU、CPU、磁盘之间分层 Offload。</td></tr><tr><td><a href="https://arxiv.org/abs/2312.07104" target="_blank" rel="noreferrer">SGLang: Efficient Execution of Structured Language Model Programs</a></td><td style="text-align:right;">2023/NeurIPS 2024</td><td>通过 RadixAttention、前缀复用和结构化程序执行优化复杂 LLM 应用。</td></tr><tr><td><a href="https://doi.org/10.1145/3694715.3695964" target="_blank" rel="noreferrer">PowerInfer: Fast Large Language Model Serving with a Consumer-grade GPU</a></td><td style="text-align:right;">2024</td><td>利用神经元激活局部性，将高频神经元放在 GPU，面向消费级 GPU 推理。</td></tr></tbody></table></div><h3 id="_2-2-attention、kv-cache-与内存" tabindex="-1">2.2 Attention、KV Cache 与内存 <a class="header-anchor" href="#_2-2-attention、kv-cache-与内存" aria-label="Permalink to “2.2 Attention、KV Cache 与内存”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>论文</th><th style="text-align:right;">年份</th><th>关键思想与影响</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2205.14135" target="_blank" rel="noreferrer">FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness</a></td><td style="text-align:right;">2022</td><td>使用 IO-aware tiling 减少 HBM 与片上 SRAM 间的数据搬运，不改变 Attention 数学结果。</td></tr><tr><td><a href="https://arxiv.org/abs/2307.08691" target="_blank" rel="noreferrer">FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning</a></td><td style="text-align:right;">2023</td><td>改进并行划分和工作负载均衡，进一步提升 GPU 利用率。</td></tr><tr><td><a href="https://arxiv.org/abs/2311.04934" target="_blank" rel="noreferrer">Prompt Cache: Modular Attention Reuse for Low-Latency Inference</a></td><td style="text-align:right;">2023</td><td>缓存可复用 Prompt 模块的 Attention 状态，适合系统提示词、模板和 RAG。</td></tr><tr><td><a href="https://arxiv.org/abs/2310.07240" target="_blank" rel="noreferrer">CacheGen: KV Cache Compression and Streaming for Fast LLM Serving</a></td><td style="text-align:right;">2023/2024</td><td>压缩并跨设备或网络流式传输 KV Cache，降低长上下文和多轮对话成本。</td></tr></tbody></table></div><h3 id="_2-3-speculative-decoding-与生成加速" tabindex="-1">2.3 Speculative Decoding 与生成加速 <a class="header-anchor" href="#_2-3-speculative-decoding-与生成加速" aria-label="Permalink to “2.3 Speculative Decoding 与生成加速”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>论文</th><th style="text-align:right;">年份</th><th>关键思想与影响</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2211.17192" target="_blank" rel="noreferrer">Fast Inference from Transformers via Speculative Decoding</a></td><td style="text-align:right;">2022/ICML 2023</td><td>小模型起草、大模型并行验证，在保持目标分布不变的前提下减少解码轮数。</td></tr><tr><td><a href="https://arxiv.org/abs/2302.01318" target="_blank" rel="noreferrer">Accelerating Large Language Model Decoding with Speculative Sampling</a></td><td style="text-align:right;">2023</td><td>将 speculative decoding 推广到 sampling，讨论接受/拒绝采样的无损性。</td></tr><tr><td><a href="https://arxiv.org/abs/2305.09781" target="_blank" rel="noreferrer">SpecInfer: Accelerating Generative LLM Serving with Tree-based Speculative Inference and Verification</a></td><td style="text-align:right;">2023</td><td>用候选 Token 树进行批量验证，适合多分支 speculative inference。</td></tr><tr><td><a href="https://arxiv.org/abs/2401.10774" target="_blank" rel="noreferrer">Medusa: Simple LLM Inference Acceleration Framework with Multiple Decoding Heads</a></td><td style="text-align:right;">2024</td><td>在目标模型上增加多个 decoding heads，不依赖独立 draft model。</td></tr></tbody></table></div><h3 id="_2-4-量化与压缩" tabindex="-1">2.4 量化与压缩 <a class="header-anchor" href="#_2-4-量化与压缩" aria-label="Permalink to “2.4 量化与压缩”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>论文</th><th style="text-align:right;">年份</th><th>关键思想与影响</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2208.07339" target="_blank" rel="noreferrer">LLM.int8(): 8-bit Matrix Multiplication for Transformers at Scale</a></td><td style="text-align:right;">2022</td><td>使用 outlier decomposition 实现大模型混合精度 INT8 推理。</td></tr><tr><td><a href="https://arxiv.org/abs/2210.17323" target="_blank" rel="noreferrer">GPTQ: Accurate Post-Training Quantization for Generative Pre-trained Transformers</a></td><td style="text-align:right;">2022</td><td>基于近似二阶信息的一次性权重量化，成为 GPTQ 类方法的基础。</td></tr><tr><td><a href="https://arxiv.org/abs/2211.10438" target="_blank" rel="noreferrer">SmoothQuant: Accurate and Efficient Post-Training Quantization for LLMs</a></td><td style="text-align:right;">2022</td><td>将 activation outlier 迁移到权重，实现更易部署的 W8A8 量化。</td></tr><tr><td><a href="https://arxiv.org/abs/2306.00978" target="_blank" rel="noreferrer">AWQ: Activation-aware Weight Quantization for LLM Compression and Acceleration</a></td><td style="text-align:right;">2023</td><td>根据激活分布识别重要权重，常用于高质量 4-bit weight-only quantization。</td></tr></tbody></table></div><h3 id="_2-5-prefill-decode-分离与集群架构" tabindex="-1">2.5 Prefill/Decode 分离与集群架构 <a class="header-anchor" href="#_2-5-prefill-decode-分离与集群架构" aria-label="Permalink to “2.5 Prefill/Decode 分离与集群架构”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>论文</th><th style="text-align:right;">年份</th><th>关键思想与影响</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2311.18677" target="_blank" rel="noreferrer">Splitwise: Efficient Generative LLM Inference Using Phase Splitting</a></td><td style="text-align:right;">2023/ISCA 2024</td><td>观察到 Prefill 和 Decode 的硬件需求不同，提出阶段分离和异构资源配置。</td></tr><tr><td><a href="https://arxiv.org/abs/2401.09670" target="_blank" rel="noreferrer">DistServe: Disaggregating Prefill and Decoding for Goodput-optimized LLM Serving</a></td><td style="text-align:right;">2024</td><td>将两个阶段部署到不同实例，联合优化 TTFT、TPOT 和 Goodput。</td></tr><tr><td><a href="https://arxiv.org/abs/2403.02310" target="_blank" rel="noreferrer">Sarathi-Serve: Taming Throughput-Latency Tradeoff in LLM Inference</a></td><td style="text-align:right;">2024</td><td>通过 Chunked Prefill 和调度策略，减少长 Prompt 对 Decode 请求的干扰。</td></tr></tbody></table></div><h3 id="_2-6-综述入口" tabindex="-1">2.6 综述入口 <a class="header-anchor" href="#_2-6-综述入口" aria-label="Permalink to “2.6 综述入口”">​</a></h3><ul><li><a href="https://arxiv.org/abs/2312.15234" target="_blank" rel="noreferrer">Towards Efficient Generative LLM Serving: A Survey from Algorithms to Systems</a>：从算法、模型压缩到系统架构建立完整地图。</li><li><a href="https://arxiv.org/abs/2404.14294" target="_blank" rel="noreferrer">A Survey on Efficient Inference for Large Language Models</a>：覆盖量化、剪枝、KV Cache、并行和服务优化。</li></ul><h2 id="_3-2024–2026-前沿进展" tabindex="-1">3. 2024–2026 前沿进展 <a class="header-anchor" href="#_3-2024–2026-前沿进展" aria-label="Permalink to “3. 2024–2026 前沿进展”">​</a></h2><h3 id="_3-1-attention-engine-与长上下文-prefill" tabindex="-1">3.1 Attention Engine 与长上下文 Prefill <a class="header-anchor" href="#_3-1-attention-engine-与长上下文-prefill" aria-label="Permalink to “3.1 Attention Engine 与长上下文 Prefill”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>工作</th><th>年份/状态</th><th>新进展与关注点</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2407.08608" target="_blank" rel="noreferrer">FlashAttention-3</a></td><td>2024，NeurIPS</td><td>面向 Hopper 引入异步执行和 FP8，说明新一代 Attention Kernel 越来越依赖具体硬件流水线。</td></tr><tr><td><a href="https://arxiv.org/abs/2501.01005" target="_blank" rel="noreferrer">FlashInfer: Efficient and Customizable Attention Engine for LLM Inference Serving</a></td><td>2025，预印本/开源</td><td>将 Prefill、Decode、Paged KV Cache、采样等能力组织为可组合推理 Kernel，适合作为框架底层执行层来研究。</td></tr><tr><td><a href="https://arxiv.org/abs/2407.02490" target="_blank" rel="noreferrer">MInference 1.0</a></td><td>2024，NeurIPS</td><td>根据输入动态选择稀疏 Attention 模式，重点降低百万 Token 级上下文的 Prefill 开销。</td></tr><tr><td><a href="https://arxiv.org/abs/2406.10774" target="_blank" rel="noreferrer">Quest: Query-Aware Sparsity for Efficient Long-Context LLM Inference</a></td><td>2024</td><td>以 Query 感知的页级选择减少 Decode 期间需要读取的 KV 数据。</td></tr><tr><td><a href="https://aclanthology.org/2025.acl-long.1126/" target="_blank" rel="noreferrer">Native Sparse Attention</a></td><td>2025，ACL</td><td>将压缩、选择和滑动窗口结合为可训练且硬件友好的原生稀疏 Attention。</td></tr><tr><td><a href="https://doi.org/10.14778/3796195.3796212" target="_blank" rel="noreferrer">RetroInfer: A Vector Storage Engine for Scalable Long-Context LLM Inference</a></td><td>2026，PVLDB</td><td>将长上下文 KV 访问视为向量存储问题，代表存储系统与推理引擎融合的方向。</td></tr></tbody></table></div><p>趋势判断：FlashAttention 解决“精确 Attention 如何高效搬运数据”，FlashInfer 进一步解决“服务系统中多种 Attention 形态如何统一执行”，而 MInference、Quest、NSA 等工作开始减少真正需要计算或读取的 Token 数量。</p><h3 id="_3-2-kv-cache-压缩、复用与数据面" tabindex="-1">3.2 KV Cache 压缩、复用与数据面 <a class="header-anchor" href="#_3-2-kv-cache-压缩、复用与数据面" aria-label="Permalink to “3.2 KV Cache 压缩、复用与数据面”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>工作</th><th>年份/状态</th><th>新进展与关注点</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2402.02750" target="_blank" rel="noreferrer">KIVI: A Tuning-Free Asymmetric 2bit Quantization for KV Cache</a></td><td>2024，ICML</td><td>针对 Key 和 Value 的分布差异采用非对称 2-bit 量化，降低长上下文 KV 显存。</td></tr><tr><td><a href="https://arxiv.org/abs/2401.18079" target="_blank" rel="noreferrer">KVQuant: Towards 10 Million Context Length LLM Inference</a></td><td>2024</td><td>从 per-channel、敏感值和非均匀量化角度压缩 KV Cache。</td></tr><tr><td><a href="https://arxiv.org/abs/2404.14469" target="_blank" rel="noreferrer">SnapKV</a></td><td>2024，NeurIPS</td><td>根据 Observation Window 选择重要 KV 位置，压缩生成阶段需要保留的缓存。</td></tr><tr><td><a href="https://arxiv.org/abs/2405.16444" target="_blank" rel="noreferrer">CacheBlend</a></td><td>2024/EuroSys 2025</td><td>面向 RAG 重用多个知识块的 KV Cache，并选择性重算跨块 Attention。</td></tr><tr><td><a href="https://arxiv.org/abs/2405.04437" target="_blank" rel="noreferrer">vAttention</a></td><td>2024/ASPLOS 2025</td><td>利用操作系统虚拟内存按需分配连续 KV 地址空间，探索不使用 PagedAttention 的动态管理路线。</td></tr><tr><td><a href="https://doi.org/10.1145/3695053.3731019" target="_blank" rel="noreferrer">Oaken</a></td><td>2025，ISCA</td><td>联合在线与离线 KV 量化，在服务运行时平衡精度、带宽和容量。</td></tr></tbody></table></div><p>当前 KV Cache 优化已经从单机显存分配扩展到三个层次：单 Token 表示压缩、跨请求前缀复用、跨机器缓存传输。三者的瓶颈和质量风险不同，评测时应分开报告。</p><p>CacheBlend、vAttention 和 Oaken 在下表的不同主题中再次出现，是因为它们同时涉及缓存算法、内存管理和服务系统；重复出现用于强调交叉影响，不代表独立工作被重复统计。</p><h3 id="_3-3-speculative-decoding-2-0" tabindex="-1">3.3 Speculative Decoding 2.0 <a class="header-anchor" href="#_3-3-speculative-decoding-2-0" aria-label="Permalink to “3.3 Speculative Decoding 2.0”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>工作</th><th>年份/状态</th><th>新进展与关注点</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2401.15077" target="_blank" rel="noreferrer">EAGLE</a></td><td>2024，ICML</td><td>在特征层而非纯 Token 层预测 Draft，提升接受率和生成速度。</td></tr><tr><td><a href="https://arxiv.org/abs/2406.16858" target="_blank" rel="noreferrer">EAGLE-2</a></td><td>2024</td><td>使用动态 Draft Tree，根据上下文置信度调整候选树结构。</td></tr><tr><td><a href="https://arxiv.org/abs/2404.16710" target="_blank" rel="noreferrer">LayerSkip</a></td><td>2024，ACL</td><td>通过 Early Exit 让同一个模型承担 Draft 和 Verify，实现 self-speculative decoding。</td></tr><tr><td><a href="https://arxiv.org/abs/2503.01840" target="_blank" rel="noreferrer">EAGLE-3</a></td><td>2025，预印本</td><td>改进训练时特征融合与测试时 Draft，代表 feature-level speculation 的继续演进。</td></tr></tbody></table></div><p>新一代方法不再只依赖“小模型猜、大模型验”。研究重点转向动态候选树、同模型 Early Exit、特征层 Draft，以及服务系统中接受率、验证 Batch 和调度策略的联合优化。推理框架的端到端收益仍强依赖具体模型和采样参数。</p><h3 id="_3-4-低比特推理与系统协同" tabindex="-1">3.4 低比特推理与系统协同 <a class="header-anchor" href="#_3-4-低比特推理与系统协同" aria-label="Permalink to “3.4 低比特推理与系统协同”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>工作</th><th>年份/状态</th><th>新进展与关注点</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2404.00456" target="_blank" rel="noreferrer">QuaRot: Outlier-Free 4-Bit Inference in Rotated LLMs</a></td><td>2024，NeurIPS</td><td>用旋转变换消除异常值，使权重、激活和 KV Cache 的 4-bit 量化更可行。</td></tr><tr><td><a href="https://arxiv.org/abs/2405.16406" target="_blank" rel="noreferrer">SpinQuant</a></td><td>2024</td><td>将旋转矩阵变为可学习参数，降低旋转量化的精度损失。</td></tr><tr><td><a href="https://arxiv.org/abs/2405.04532" target="_blank" rel="noreferrer">QServe: W4A8KV4 Quantization and System Co-design</a></td><td>2024</td><td>同时优化 W4A8KV4 数值格式、Kernel 和服务系统，强调量化必须有硬件 Kernel 配合。</td></tr><tr><td><a href="https://doi.org/10.1145/3695053.3731019" target="_blank" rel="noreferrer">Oaken</a></td><td>2025，ISCA</td><td>将 KV4 从离线模型压缩问题扩展为在线服务策略。</td></tr></tbody></table></div><p>量化选型不能只看“4-bit”标签。Weight-only、W8A8、W4A8 和 KV4 对 Prefill、Decode、显存容量以及硬件支持的影响不同；没有对应高效 Kernel 时，理论位宽降低不一定转化为吞吐提升。</p><h3 id="_3-5-pd-解耦、分布式缓存与路由" tabindex="-1">3.5 PD 解耦、分布式缓存与路由 <a class="header-anchor" href="#_3-5-pd-解耦、分布式缓存与路由" aria-label="Permalink to “3.5 PD 解耦、分布式缓存与路由”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>工作</th><th>年份/状态</th><th>新进展与关注点</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2407.00079" target="_blank" rel="noreferrer">Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving</a></td><td>2024/2025</td><td>将 KV Cache 作为独立数据面，通过分布式缓存池和高速传输连接 Prefill、Decode 实例。</td></tr><tr><td><a href="https://arxiv.org/abs/2407.00023" target="_blank" rel="noreferrer">Preble: Efficient Distributed Prompt Scheduling for LLM Serving</a></td><td>2024</td><td>根据共享前缀和负载进行分布式 Prompt 路由，在缓存命中与负载均衡间取舍。</td></tr><tr><td><a href="https://arxiv.org/abs/2405.16444" target="_blank" rel="noreferrer">CacheBlend</a></td><td>2024/EuroSys 2025</td><td>将 RAG 的缓存复用推进到多个非连续知识块组合场景。</td></tr><tr><td><a href="https://doi.org/10.1145/3669940.3707256" target="_blank" rel="noreferrer">vAttention</a></td><td>ASPLOS 2025</td><td>重新审视 PagedAttention 的软件分页成本，以虚拟内存机制支持动态 KV 分配。</td></tr></tbody></table></div><p>这一方向的核心已不只是“把 Prefill 和 Decode 放到不同 GPU”，而是构建独立 KV Cache 数据面，并让路由器感知前缀命中、传输成本、SLO 和异构硬件。</p><h3 id="_3-6-模型架构开始为推理而设计" tabindex="-1">3.6 模型架构开始为推理而设计 <a class="header-anchor" href="#_3-6-模型架构开始为推理而设计" aria-label="Permalink to “3.6 模型架构开始为推理而设计”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>工作</th><th style="text-align:right;">年份</th><th>与推理相关的变化</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2405.04434" target="_blank" rel="noreferrer">DeepSeek-V2</a></td><td style="text-align:right;">2024</td><td>Multi-head Latent Attention（MLA）压缩 KV 表示，MoE 降低每 Token 激活参数量。</td></tr><tr><td><a href="https://arxiv.org/abs/2412.19437" target="_blank" rel="noreferrer">DeepSeek-V3 Technical Report</a></td><td style="text-align:right;">2024/2025</td><td>延续 MLA/MoE，并使用 Multi-Token Prediction，为后续 speculative decoding 提供结构基础。</td></tr><tr><td><a href="https://arxiv.org/abs/2501.12948" target="_blank" rel="noreferrer">DeepSeek-R1</a></td><td style="text-align:right;">2025</td><td>长 Chain-of-Thought 让输出长度和 Decode 成本显著上升，推动按 Goodput、KV 容量和长输出调度重新评测推理系统。</td></tr></tbody></table></div><p>这类工作表明推理优化正在前移到模型设计阶段。未来对服务框架的评测需要区分 MHA、GQA、MLA、Dense、MoE 和 Hybrid SSM 等模型结构，不能只用参数量作为成本代理。</p><h2 id="_4-经典博客与工程资料" tabindex="-1">4. 经典博客与工程资料 <a class="header-anchor" href="#_4-经典博客与工程资料" aria-label="Permalink to “4. 经典博客与工程资料”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>资料</th><th>推荐理由</th></tr></thead><tbody><tr><td><a href="https://vllm.ai/blog/2023-06-20-vllm" target="_blank" rel="noreferrer">vLLM: Easy, Fast, and Cheap LLM Serving</a></td><td>vLLM 官方介绍，适合理解 PagedAttention、连续批处理和服务设计。</td></tr><tr><td><a href="https://www.anyscale.com/blog/continuous-batching-llm-inference" target="_blank" rel="noreferrer">Anyscale: Continuous Batching for LLM Inference</a></td><td>用工程视角解释 iteration-level scheduling 的收益。</td></tr><tr><td><a href="https://developer.nvidia.com/blog/mastering-llm-techniques-inference-optimization/" target="_blank" rel="noreferrer">NVIDIA: Mastering LLM Techniques — Inference Optimization</a></td><td>系统覆盖并行、量化、KV Cache、批处理和 speculative decoding。</td></tr><tr><td><a href="https://pytorch.org/blog/flash-decoding/" target="_blank" rel="noreferrer">PyTorch: Flash-Decoding</a></td><td>解释长序列 Decode 阶段的并行化和 Attention 优化。</td></tr><tr><td><a href="https://pytorch.org/blog/accelerating-generative-ai-2/" target="_blank" rel="noreferrer">PyTorch: Accelerating Generative AI</a></td><td>介绍 PyTorch SDPA、编译和 Kernel 层面的生成式 AI 优化。</td></tr><tr><td><a href="https://huggingface.co/blog/assisted-generation" target="_blank" rel="noreferrer">Hugging Face: Assisted Generation</a></td><td>speculative decoding 的直观工程说明。</td></tr><tr><td><a href="https://huggingface.co/docs/text-generation-inference/index" target="_blank" rel="noreferrer">Hugging Face Text Generation Inference</a></td><td>生产部署、量化、张量并行和服务接口的实用文档。</td></tr><tr><td><a href="https://www.lmsys.org/blog/2024-01-17-sglang/" target="_blank" rel="noreferrer">LMSYS: SGLang</a></td><td>解释 RadixAttention、结构化生成和 Prefix Reuse。</td></tr><tr><td><a href="https://github.com/NVIDIA/TensorRT-LLM" target="_blank" rel="noreferrer">TensorRT-LLM</a></td><td>NVIDIA 硬件生态下的高性能推理实现，可与 vLLM 对照学习。</td></tr></tbody></table></div><h3 id="_4-1-近期工程演进" tabindex="-1">4.1 近期工程演进 <a class="header-anchor" href="#_4-1-近期工程演进" aria-label="Permalink to “4.1 近期工程演进”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>资料</th><th style="text-align:right;">时间</th><th>推荐理由</th></tr></thead><tbody><tr><td><a href="https://vllm.ai/blog/2025-01-27-v1-alpha-release" target="_blank" rel="noreferrer">vLLM V1: A Major Upgrade to vLLM&#39;s Core Architecture</a></td><td style="text-align:right;">2025</td><td>了解 vLLM 新核心架构、统一调度器、Prefix Cache 和执行路径重构。</td></tr><tr><td><a href="https://github.com/ai-dynamo/dynamo" target="_blank" rel="noreferrer">NVIDIA Dynamo</a></td><td style="text-align:right;">2025–</td><td>面向推理集群的开源运行时，重点覆盖智能路由、PD 解耦、KV 传输和多后端。</td></tr><tr><td><a href="https://llm-d.ai/" target="_blank" rel="noreferrer">llm-d</a></td><td style="text-align:right;">2025–</td><td>Kubernetes 原生的分布式推理方案，关注推理调度、路由和 KV Cache 基础设施。</td></tr><tr><td><a href="https://github.com/flashinfer-ai/flashinfer" target="_blank" rel="noreferrer">FlashInfer</a></td><td style="text-align:right;">2025–</td><td>可组合 Attention、采样和通信 Kernel，适合跟踪推理框架底层执行层。</td></tr><tr><td><a href="https://vllm.ai/blog/2026-04-21-hybrid-ssm-disagg" target="_blank" rel="noreferrer">Disaggregated Serving for Hybrid SSM Models in vLLM</a></td><td style="text-align:right;">2026</td><td>说明 PD 解耦如何扩展到 Attention 与 SSM 混合模型，以及状态迁移的新问题。</td></tr><tr><td><a href="https://vllm.ai/blog/2026-07-16-keeping-vllm-production-quality" target="_blank" rel="noreferrer">Keeping vLLM Production Quality</a></td><td style="text-align:right;">2026</td><td>从 CI、性能回归、Benchmark 和发布流程理解生产级推理框架如何保持性能质量。</td></tr></tbody></table></div><h3 id="_4-2-运行时架构与分布式执行" tabindex="-1">4.2 运行时架构与分布式执行 <a class="header-anchor" href="#_4-2-运行时架构与分布式执行" aria-label="Permalink to “4.2 运行时架构与分布式执行”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>资料</th><th>推荐理由</th></tr></thead><tbody><tr><td><a href="https://vllm.ai/blog/2025-09-05-anatomy-of-vllm" target="_blank" rel="noreferrer">Inside vLLM: Anatomy of a High-Throughput LLM Inference System</a></td><td>从请求进入、调度、KV Block 管理到 Worker 执行理解完整数据路径。</td></tr><tr><td><a href="https://vllm.ai/blog/2025-02-17-distributed-inference" target="_blank" rel="noreferrer">Distributed Inference with vLLM</a></td><td>解释单节点与多节点 Tensor Parallel、Pipeline Parallel 和部署拓扑。</td></tr><tr><td><a href="https://vllm.ai/blog/2025-08-20-torch-compile" target="_blank" rel="noreferrer">Introduction to torch.compile and How It Works with vLLM</a></td><td>理解动态图捕获、编译缓存、Custom Op 和推理框架的编译边界。</td></tr><tr><td><a href="https://developer.nvidia.com/blog/optimizing-inference-on-llms-with-tensorrt-llm-now-publicly-available/" target="_blank" rel="noreferrer">Optimizing Inference on LLMs with TensorRT-LLM</a></td><td>从 NVIDIA Kernel、量化和 In-flight Batching 视角理解另一条推理栈。</td></tr><tr><td><a href="https://docs.ray.io/en/latest/serve/llm/index.html" target="_blank" rel="noreferrer">Ray Serve LLM</a></td><td>关注模型副本、自动扩缩、路由和 Python 服务编排，而不只关注单进程 Engine。</td></tr></tbody></table></div><h3 id="_4-3-kv-cache、连接器与解耦服务" tabindex="-1">4.3 KV Cache、连接器与解耦服务 <a class="header-anchor" href="#_4-3-kv-cache、连接器与解耦服务" aria-label="Permalink to “4.3 KV Cache、连接器与解耦服务”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>资料</th><th>推荐理由</th></tr></thead><tbody><tr><td><a href="https://vllm.ai/blog/2026-04-22-fp8-kvcache" target="_blank" rel="noreferrer">The State of FP8 KV-Cache and Attention Quantization in vLLM</a></td><td>说明 FP8 KV Cache 的 Kernel、精度校准和硬件支持现状。</td></tr><tr><td><a href="https://vllm.ai/blog/2026-05-06-mooncake-store" target="_blank" rel="noreferrer">Serving Agentic Workloads at Scale with vLLM x Mooncake</a></td><td>展示 Agent 多轮工作负载下 Session KV Cache 的跨实例复用。</td></tr><tr><td><a href="https://docs.lmcache.ai/" target="_blank" rel="noreferrer">LMCache Documentation</a></td><td>包含 vLLM/SGLang 集成、CPU/Disk/Remote Offload 和 KV Connector 实践。</td></tr><tr><td><a href="https://github.com/kvcache-ai/Mooncake" target="_blank" rel="noreferrer">Mooncake</a></td><td>KVCache-centric 分布式存储与传输实现，可用于研究 PD 解耦的数据面。</td></tr><tr><td><a href="https://github.com/ai-dynamo/nixl" target="_blank" rel="noreferrer">NIXL</a></td><td>为 GPU、CPU、对象存储等内存层次提供统一的数据移动接口。</td></tr></tbody></table></div><h3 id="_4-4-speculative-decoding、moe-与量化" tabindex="-1">4.4 Speculative Decoding、MoE 与量化 <a class="header-anchor" href="#_4-4-speculative-decoding、moe-与量化" aria-label="Permalink to “4.4 Speculative Decoding、MoE 与量化”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>资料</th><th>推荐理由</th></tr></thead><tbody><tr><td><a href="https://vllm.ai/blog/2024-10-17-spec-decode" target="_blank" rel="noreferrer">How Speculative Decoding Boosts vLLM Performance</a></td><td>给出 Draft Model、N-gram 和典型接受率/开销分析。</td></tr><tr><td><a href="https://vllm.ai/blog/2026-05-26-eagle-3-1" target="_blank" rel="noreferrer">EAGLE 3.1 in vLLM</a></td><td>了解 Feature-level Draft 如何进入生产推理框架。</td></tr><tr><td><a href="https://vllm.ai/blog/2026-07-28-speculators-parallel-drafting" target="_blank" rel="noreferrer">Parallel All the Way Down</a></td><td>讨论并行 Draft 与多 Token 生成的新工程路径。</td></tr><tr><td><a href="https://vllm.ai/blog/2026-05-14-elastic-expert-parallelism" target="_blank" rel="noreferrer">Elastic Expert Parallelism in vLLM</a></td><td>关注 MoE 模型 Expert 放置、负载变化和弹性并行。</td></tr><tr><td><a href="https://nvidia.github.io/TensorRT-LLM/features/quantization.html" target="_blank" rel="noreferrer">TensorRT-LLM Quantization</a></td><td>对照 FP8、INT8、INT4、AWQ、GPTQ 和 KV Cache 量化的硬件支持。</td></tr></tbody></table></div><h3 id="_4-5-benchmark、容量规划与性能回归" tabindex="-1">4.5 Benchmark、容量规划与性能回归 <a class="header-anchor" href="#_4-5-benchmark、容量规划与性能回归" aria-label="Permalink to “4.5 Benchmark、容量规划与性能回归”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>资料</th><th>推荐理由</th></tr></thead><tbody><tr><td><a href="https://docs.vllm.ai/en/latest/cli/bench/serve/" target="_blank" rel="noreferrer">vLLM Bench Serve</a></td><td>生成请求负载并统计 TTFT、TPOT、ITL 和端到端吞吐。</td></tr><tr><td><a href="https://docs.sglang.io/docs/developer_guide/benchmark_and_profiling" target="_blank" rel="noreferrer">SGLang Benchmark and Profiling</a></td><td>覆盖离线吞吐、在线服务和 Nsight Profiling。</td></tr><tr><td><a href="https://nvidia.github.io/TensorRT-LLM/performance/perf-benchmarking.html" target="_blank" rel="noreferrer">TensorRT-LLM Performance Benchmarking</a></td><td>学习固定输入/输出长度和 IFB 场景的标准化测试。</td></tr><tr><td><a href="https://docs.nvidia.com/deeplearning/triton-inference-server/user-guide/docs/perf_analyzer/genai-perf/README.html" target="_blank" rel="noreferrer">GenAI-Perf</a></td><td>对 OpenAI-compatible、Triton 和 TensorRT-LLM 服务进行统一压测。</td></tr><tr><td><a href="https://github.com/vllm-project/guidellm" target="_blank" rel="noreferrer">GuideLLM</a></td><td>构造并发、请求率和数据集驱动的负载，适合做引擎横向比较。</td></tr><tr><td><a href="https://github.com/microsoft/vidur" target="_blank" rel="noreferrer">Vidur</a></td><td>用模拟器做 GPU 类型、并行度、Batch 和请求分布的容量规划。</td></tr></tbody></table></div><p>完整实验路线见 <a href="#_5-论文方法与工程选型对照">论文方法与工程选型对照</a>。</p><h2 id="推荐阅读" tabindex="-1">推荐阅读 <a class="header-anchor" href="#推荐阅读" aria-label="Permalink to “推荐阅读”">​</a></h2><ol><li>先读两篇综述，建立术语和技术地图。</li><li>读 Orca，理解 iteration-level scheduling。</li><li>读 PagedAttention，理解 KV Cache 为什么成为服务系统核心。</li><li>从 FlashAttention 读到 FlashAttention-3 和 FlashInfer，理解 Kernel 如何走向硬件专用化和服务化。</li><li>从 speculative decoding 读到 EAGLE-2/3 与 LayerSkip，理解动态树和 self-speculation。</li><li>从 GPTQ、SmoothQuant、AWQ 读到 QuaRot、QServe，理解量化与 Kernel 的系统协同。</li><li>从 DistServe、Splitwise 读到 Mooncake、Preble，理解 KV Cache 数据面和缓存感知路由。</li><li>按 <a href="#_5-论文方法与工程选型对照">论文方法与工程选型对照</a> 完成包含真实请求分布的基准实验。</li></ol><h2 id="_5-论文方法与工程选型对照" tabindex="-1">5. 论文方法与工程选型对照 <a class="header-anchor" href="#_5-论文方法与工程选型对照" aria-label="Permalink to “5. 论文方法与工程选型对照”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>目标</th><th>优先关注的技术</th></tr></thead><tbody><tr><td>单卡部署</td><td>AWQ/GPTQ、FlashAttention-2/3、vLLM</td></tr><tr><td>多卡部署</td><td>张量并行、流水线并行、vLLM、SGLang 或 TensorRT-LLM</td></tr><tr><td>高并发在线服务</td><td>PagedAttention、Continuous Batching</td></tr><tr><td>长 Prompt 或 RAG</td><td>Prefix Caching、CacheBlend、Chunked Prefill、MInference</td></tr><tr><td>降低输出延迟</td><td>Speculative Decoding、EAGLE、LayerSkip</td></tr><tr><td>多租户大规模集群</td><td>PD Disaggregation、Mooncake、Preble、Dynamo、llm-d</td></tr><tr><td>KV Cache 容量受限</td><td>KIVI、KVQuant、SnapKV、Oaken</td></tr><tr><td>低比特端到端推理</td><td>QuaRot、SpinQuant、QServe，确认目标硬件 Kernel 支持</td></tr><tr><td>消费级 GPU 或 CPU Offload</td><td>FlexGen、PowerInfer</td></tr></tbody></table></div><h2 id="_6-阅读和实验时的注意事项" tabindex="-1">6. 阅读和实验时的注意事项 <a class="header-anchor" href="#_6-阅读和实验时的注意事项" aria-label="Permalink to “6. 阅读和实验时的注意事项”">​</a></h2><ul><li>论文中的加速比依赖模型大小、输入/输出长度、Batch Size、GPU 型号、量化精度和延迟 SLO，不能直接横向比较。</li><li>评测至少同时记录 TTFT、TPOT/ITL、吞吐、显存峰值和请求完成率；只看 tokens/s 容易掩盖在线延迟退化。</li><li>Prefill 和 Decode 的瓶颈不同，建议分阶段报告结果，并明确是否启用了 Prefix Cache、量化和 speculative decoding。</li><li>对量化方法应同时评测困惑度、任务准确率和端到端吞吐，不能只比较模型文件大小。</li><li>对 PD 解耦系统必须报告 KV 传输带宽、缓存命中率、跨节点拓扑和路由策略；忽略数据面成本会高估收益。</li><li>对 reasoning model 应报告输出长度分布、推理预算和截断策略，普通短输出基准无法代表其真实 Decode 负载。</li><li>对 2025–2026 年预印本和快速迭代项目，应复现实验或核对稳定版本文档，不把仓库中的单次性能数字视为通用结论。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>当前 LLM 推理优化可以按三条主线理解：</p><ul><li><strong>减少每一步的工作量</strong>：稀疏 Attention、KV 压缩和 speculative decoding。</li><li><strong>更有效地搬运和复用状态</strong>：PagedAttention、Prefix Cache、KV Offload 和分布式 KV 数据面。</li><li><strong>让硬件持续保持有效工作</strong>：Continuous Batching、专用 Kernel、量化、并行和 PD 解耦。</li></ul><p>最可靠的学习方式是先用 vLLM 或 SGLang 建立基线，再一次只改变一个变量，最后用真实请求分布验证论文或博客中的性能结论。具体实验步骤见 <a href="#_5-论文方法与工程选型对照">论文方法与工程选型对照</a>。</p>`,60)])}var p=c(d,[[`render`,f]]);export{u as __pageData,p as default};